    "Read as {0}: its party and names checked out against this ROM. Off: {1}. The library tags it PARTIALLY SUPPORTED." to Tr(ja = "{0}として よみます: てもちと なまえは この ROMと あいました。 オフ: {1}。 ライブラリでは 「いちぶ たいおう」です。", fr = "Lu comme {0} : équipe et noms vérifiés sur cette ROM. Désactivé : {1}. La bibliothèque l'indique PARTIEL.", de = "Gelesen als {0}: Team und Namen passen zu diesem ROM. Aus: {1}. Die Bibliothek markiert es als TEILWEISE.", it = "Letto come {0}: squadra e nomi verificati su questa ROM. Spento: {1}. La libreria lo segna PARZIALE.", es = "Leído como {0}: equipo y nombres comprobados en esta ROM. Desactivado: {1}. La biblioteca lo marca PARCIAL.", br = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca o marca como PARCIAL.", pt = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca marca-o como PARCIAL.", zh = "已识别为{0}：队伍和名称与此 ROM 一致。未启用：{1}。游戏库将其标记为部分支持。"),
    "Your party doesn't read as {0} - it does as {1}. Pick the game you're playing." to Tr(ja = "てもちが {0}として よめません - {1}なら よめます。 あそんでいる ゲームを えらんでください。", fr = "Votre équipe ne se lit pas comme {0} - mais comme {1}. Choisissez votre jeu.", de = "Dein Team liest sich nicht als {0} - aber als {1}. Wähle dein Spiel.", it = "La tua squadra non si legge come {0} - ma come {1}. Scegli il tuo gioco.", es = "Tu equipo no se lee como {0} - pero sí como {1}. Elige tu juego.", br = "Sua equipe não é lida como {0} - e sim como {1}. Escolha o seu jogo.", pt = "A sua equipe não é lida como {0} - mas sim como {1}. Escolha o seu jogo.", zh = "队伍数据与{0}不符，却与{1}相符。请选择你正在玩的游戏。"),
    "Your party doesn't read as {0}: names and sprites may be wrong. Pick the game you're playing, or keep it." to Tr(ja = "てもちが {0}として よめません: なまえや えが ちがうかも。 あそんでいる ゲームを えらぶか このままに。", fr = "Votre équipe ne se lit pas comme {0} : noms et sprites peuvent être faux. Choisissez votre jeu, ou gardez-le.", de = "Dein Team liest sich nicht als {0}: Namen und Sprites können falsch sein. Wähle dein Spiel oder behalte es.", it = "La tua squadra non si legge come {0}: nomi e sprite potrebbero essere sbagliati. Scegli il tuo gioco, o tienilo.", es = "Tu equipo no se lee como {0}: nombres y sprites pueden fallar. Elige tu juego o mantenlo.", br = "Sua equipe não é lida como {0}: nomes e sprites podem estar errados. Escolha o seu jogo, ou mantenha.", pt = "A sua equipe não é lida como {0}: nomes e sprites podem estar errados. Escolha o seu jogo, ou mantenha-o.", zh = "队伍数据与{0}不符，名称和图像可能不正确。请选择你正在玩的游戏，或保留当前选择。"),
    "You said it's none of the games PokéDaisy knows. If it's a version of one, pick it." to Tr(ja = "PokéDaisyの しる ゲームでは ないと えらびました。 どれかの バージョンなら えらんでください。", fr = "Vous avez dit que ce n'est aucun des jeux connus de PokéDaisy. Si c'en est une version, choisissez-le.", de = "Du hast gesagt, es ist keines der Spiele, die PokéDaisy kennt. Ist es eine Version davon, wähle es.", it = "Hai detto che non è nessuno dei giochi noti a PokéDaisy. Se ne è una versione, sceglilo.", es = "Dijiste que no es ninguno de los juegos que conoce PokéDaisy. Si es una versión de uno, elígelo.", br = "Você disse que não é nenhum dos jogos que o PokéDaisy conhece. Se for uma versão de um deles, escolha-o.", pt = "Disse que não é nenhum dos jogos que o PokéDaisy conhece. Se for uma versão de um deles, escolha-o.", zh = "你选择了以上都不是。如果它基于 PokéDaisy 已知的游戏，请选择该游戏。"),
    "the POKéDEX" to Tr(ja = "ずかん", fr = "le POKéDEX", de = "der POKéDEX", it = "il POKéDEX", es = "la POKéDEX", br = "a POKéDEX", pt = "a POKéDEX", zh = "图鉴"),
    "the GUIDE's live pages" to Tr(ja = "ガイドの ライブページ", fr = "les pages en direct du GUIDE", de = "die Live-Seiten des GUIDES", it = "le pagine dal vivo della GUIDA", es = "las páginas en vivo de la GUÍA", br = "as páginas ao vivo do GUIA", pt = "as páginas em direto do GUIA", zh = "攻略的实时页面"),
    "item descriptions" to Tr(ja = "どうぐの せつめい", fr = "les descriptions d'objets", de = "die Item-Beschreibungen", it = "le descrizioni degli strumenti", es = "las descripciones de objetos", br = "as descrições de itens", pt = "as descrições de itens", zh = "道具说明"),
    "Read as {0}: everything matched, so it works like a supported game." to Tr(ja = "{0}として よみます: すべて あったので サポートずみと おなじです。", fr = "Lu comme {0} : tout correspond, il marche comme un jeu pris en charge.", de = "Gelesen als {0}: alles passt, es läuft wie ein unterstütztes Spiel.", it = "Letto come {0}: tutto combacia, funziona come un gioco supportato.", es = "Leído como {0}: todo encaja, funciona como un juego compatible.", br = "Lido como {0}: tudo confere, então funciona como um jogo suportado.", pt = "Lido como {0}: tudo corresponde, por isso funciona como um jogo suportado.", zh = "已识别为{0}：所有数据均匹配，可按受支持游戏使用。"),
    "ASK FOR SUPPORT" to Tr(ja = "サポートを たのむ", fr = "DEMANDER LE SUPPORT", de = "SUPPORT ANFRAGEN", it = "CHIEDI SUPPORTO", es = "PEDIR SOPORTE", br = "PEDIR SUPORTE", pt = "PEDIR SUPORTE", zh = "请求支持"),
    "Opens a game request with the ROM's file name and SHA-1 - never the ROM itself." to Tr(ja = "ROMの ファイルめいと SHA-1で ゲームの リクエストを ひらきます - ROMは おくりません。", fr = "Ouvre une demande de jeu avec le nom du fichier ROM et son SHA-1 - jamais la ROM.", de = "Öffnet eine Spielanfrage mit Dateiname und SHA-1 des ROMs - nie das ROM selbst.", it = "Apre una richiesta di gioco con nome file e SHA-1 della ROM - mai la ROM.", es = "Abre una solicitud de juego con el nombre y el SHA-1 de la ROM - nunca la ROM.", br = "Abre um pedido de jogo com o nome do arquivo e o SHA-1 da ROM - nunca a própria ROM.", pt = "Abre um pedido de jogo com o nome do ficheiro e o SHA-1 da ROM - nunca a própria ROM.", zh = "创建游戏支持请求，包含 ROM 文件名和 SHA-1，不会发送 ROM 本身。"),
    "THIS ROM ISN'T SUPPORTED" to Tr(ja = "この ROMには たいおう していません", fr = "CETTE ROM N'EST PAS PRISE EN CHARGE", de = "DIESE ROM WIRD NICHT UNTERSTÜTZT", it = "QUESTA ROM NON È SUPPORTATA", es = "ESTA ROM NO ES COMPATIBLE", br = "ESTA ROM NÃO É SUPORTADA", pt = "ESTA ROM NÃO É SUPORTADA", zh = "不支持此 ROM"),
    "The game plays normally on the top screen, but the second screen can't read its party, map, items or battles." to Tr(ja = "ゲームは うえの がめんで ふつうに あそべますが 2つめの がめんでは てもち マップ どうぐ バトルを よみとれません。", fr = "Le jeu fonctionne normalement sur l'écran du haut, mais le second écran ne peut pas lire son équipe, sa carte, ses objets ni ses combats.", de = "Das Spiel läuft oben ganz normal, aber der zweite Bildschirm kann Team, Karte, Items und Kämpfe nicht lesen.", it = "Il gioco funziona normalmente sullo schermo superiore, ma il secondo schermo non può leggerne squadra, mappa, strumenti o lotte.", es = "El juego funciona con normalidad en la pantalla superior, pero la segunda pantalla no puede leer su equipo, mapa, objetos ni combates.", br = "O jogo funciona normalmente na tela de cima, mas a segunda tela não consegue ler a equipe, o mapa, os itens nem as batalhas.", pt = "O jogo funciona normalmente no ecrã de cima, mas o segundo ecrã não consegue ler a equipe, o mapa, os itens nem as batalhas.", zh = "上屏可以正常运行游戏，但下屏无法读取队伍、地图、道具或对战信息。"),
    "SETTINGS (the gear below) still works." to Tr(ja = "せってい (したの はぐるま) は つかえます。", fr = "OPTIONS (l'engrenage en bas) fonctionne toujours.", de = "OPTIONEN (das Zahnrad unten) funktioniert weiterhin.", it = "OPZIONI (l'ingranaggio in basso) funziona ancora.", es = "AJUSTES (el engranaje de abajo) sigue funcionando.", br = "CONFIGURAÇÕES (a engrenagem abaixo) continua funcionando.", pt = "DEFINIÇÕES (a engrenagem abaixo) continua a funcionar.", zh = "设置（下方齿轮）仍可使用。"),
    "no data yet" to Tr(ja = "まだ データが ありません", fr = "pas encore de données", de = "noch keine Daten", it = "ancora nessun dato", es = "aún no hay datos", br = "ainda sem dados", pt = "ainda sem dados", zh = "暂无数据"),
