    "Joined in {0}" to Tr(ja = "{0}で なかまに なった", fr = "Arrivé à {0}", de = "Dazugekommen in {0}", it = "Arrivato a {0}", es = "Se unió en {0}", br = "Entrou em {0}", pt = "Entrou em {0}", zh = "在{0}加入"),
    "Out of the run" to Tr(ja = "もう つかえない", fr = "Hors du défi", de = "Ausgeschieden", it = "Fuori dalla sfida", es = "Fuera del reto", br = "Fora do desafio", pt = "Fora do desafio", zh = "已退出挑战"),
    "Track a run: one catch per area, a faint is final" to Tr(ja = "1ばしょ 1ぴき、ひんしは さいごの チャレンジを きろく", fr = "Suivez un défi : une capture par zone, un K.O. est définitif", de = "Verfolge einen Lauf: ein Fang pro Gebiet, besiegt ist endgültig", it = "Segui una sfida: una cattura per zona, chi è esausto è perso", es = "Sigue un reto: una captura por zona, debilitarse es definitivo", br = "Acompanhe um desafio: uma captura por área, desmaiar é para sempre", pt = "Acompanha um desafio: uma captura por área, desmaiar é para sempre", zh = "记录挑战：每个区域只能捕捉一次，濒死后永久退出"),
    // Feature tips (FeatureTip.kt): the card over the game / on the companion.
    "ZOOM OUT, LOOK AROUND" to Tr(ja = "ズームして みまわそう", fr = "DÉZOOMEZ, REGARDEZ AUTOUR", de = "HERAUSZOOMEN, UMSEHEN", it = "ALLONTANA E GUARDATI INTORNO", es = "ALEJA Y MIRA ALREDEDOR", br = "AFASTE E OLHE AO REDOR", pt = "AFASTE E OLHE À VOLTA", zh = "缩小画面，环顾四周"),
    "With EXPAND you can see further than the game ever showed you." to Tr(ja = "ひろげる なら ゲームが みせなかった ところまで みえる。", fr = "Avec ÉTENDRE, vous voyez plus loin que le jeu ne l'a jamais montré.", de = "Mit ERWEITERN siehst du weiter, als das Spiel je gezeigt hat.", it = "Con ESPANDI vedi più lontano di quanto il gioco abbia mai mostrato.", es = "Con AMPLIAR ves más lejos de lo que el juego mostró nunca.", br = "Com EXPANDIR você vê mais longe do que o jogo já mostrou.", pt = "Com EXPANDIR vê mais longe do que o jogo alguma vez mostrou.", zh = "使用扩展画面可以看到原游戏画面以外的区域。"),
    "SHOW ME" to Tr(ja = "みせて", fr = "MONTRER", de = "ZEIG MAL", it = "MOSTRA", es = "VER", br = "MOSTRAR", pt = "MOSTRAR", zh = "查看"),
    "SEE MORE OF THE WORLD" to Tr(ja = "せかいを もっと みよう", fr = "VOYEZ PLUS DU MONDE", de = "SIEH MEHR VON DER WELT", it = "VEDI PIÙ MONDO", es = "VE MÁS DEL MUNDO", br = "VEJA MAIS DO MUNDO", pt = "VEJA MAIS DO MUNDO", zh = "看到更多世界"),
    "EXPAND draws the map past the game's edges, so the whole screen is the game. No black bars, nothing stretched." to Tr(ja = "ひろげるは ゲームの はしの そとまで マップを えがく。 がめん ぜんぶが ゲームに なる。 くろい おびも のびも なし。", fr = "ÉTENDRE dessine la carte au-delà des bords du jeu : tout l'écran devient le jeu. Ni bandes noires, ni étirement.", de = "ERWEITERN zeichnet die Karte über den Rand des Spiels hinaus, der ganze Bildschirm ist Spiel. Keine schwarzen Balken, nichts verzerrt.", it = "ESPANDI disegna la mappa oltre i bordi del gioco: tutto lo schermo è il gioco. Niente bande nere, niente stirato.", es = "AMPLIAR dibuja el mapa más allá de los bordes del juego: toda la pantalla es el juego. Sin barras negras ni estirar.", br = "EXPANDIR desenha o mapa além das bordas do jogo: a tela toda é o jogo. Sem barras pretas, nada esticado.", pt = "EXPANDIR desenha o mapa para lá das margens do jogo: o ecrã todo é o jogo. Sem barras pretas, nada esticado.", zh = "扩展画面会绘制游戏边缘之外的地图，让游戏填满屏幕，无黑边且不拉伸。"),
    "EVERYTHING IN ONE PRESS" to Tr(ja = "ボタン ひとつで なんでも", fr = "TOUT EN UNE PRESSION", de = "ALLES MIT EINEM DRUCK", it = "TUTTO CON UN TASTO", es = "TODO CON UN BOTÓN", br = "TUDO NUM BOTÃO", pt = "TUDO NUM BOTÃO", zh = "一键完成常用操作"),
    "The QUICK MENU opens the PC, flies, gets on your bike or saves a state without leaving the field." to Tr(ja = "クイックメニューで パソコン そらをとぶ じてんしゃ ステート セーブが その ばで できる。", fr = "Le MENU RAPIDE ouvre le PC, fait voler, sort le vélo ou sauve un état sans quitter la carte.", de = "Das SCHNELLMENÜ öffnet den PC, fliegt, holt das Rad oder sichert einen Spielstand, direkt unterwegs.", it = "Il MENU RAPIDO apre il PC, vola, prende la bici o salva uno stato senza lasciare la mappa.", es = "El MENÚ RÁPIDO abre el PC, vuela, saca la bici o guarda un estado sin salir del mapa.", br = "O MENU RÁPIDO abre o PC, voa, pega a bicicleta ou salva um estado sem sair do mapa.", pt = "O MENU RÁPIDO abre o PC, voa, tira a bicicleta ou guarda um estado sem sair do mapa.", zh = "使用快捷菜单，无需离开场景即可打开电脑、飞翔、骑车或保存即时存档。"),
    "OPEN IT" to Tr(ja = "ひらく", fr = "OUVRIR", de = "ÖFFNEN", it = "APRI", es = "ABRIR", br = "ABRIR", pt = "ABRIR", zh = "打开"),
    "TAP THE HUD" to Tr(ja = "HUDを タッチ", fr = "TOUCHEZ LE HUD", de = "TIPP AUFS HUD", it = "TOCCA L'HUD", es = "TOCA EL HUD", br = "TOQUE NO HUD", pt = "TOQUE NO HUD", zh = "点按 HUD"),
    "Tap a party icon for its summary, the minimap for the map, BAG to use an item." to Tr(ja = "てもちの アイコンで ようす ミニマップで マップ バッグで どうぐを つかえる。", fr = "Touchez une icône de l'équipe pour son résumé, la mini carte pour la carte, SAC pour utiliser un objet.", de = "Tipp ein Teamsymbol für die Übersicht, die Minikarte für die Karte, BEUTEL für ein Item.", it = "Tocca un'icona della squadra per il riepilogo, la minimappa per la mappa, BORSA per usare uno strumento.", es = "Toca un icono del equipo para su resumen, el minimapa para el mapa, MOCHILA para usar un objeto.", br = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item.", pt = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item.", zh = "点按队伍图标查看详情，点按小地图打开地图，点按背包使用道具。"),
    "THE PC, FROM ANYWHERE" to Tr(ja = "どこでも パソコン", fr = "LE PC, OÙ QUE VOUS SOYEZ", de = "DER PC, ÜBERALL", it = "IL PC, OVUNQUE", es = "EL PC, DONDE SEA", br = "O PC, DE QUALQUER LUGAR", pt = "O PC, EM QUALQUER LADO", zh = "随处使用电脑"),
    "Open your boxes from the BAG tab or the QUICK MENU. No walk back to town." to Tr(ja = "バッグか クイックメニューから ボックスを ひらける。 まちまで もどらなくて いい。", fr = "Ouvrez vos boîtes depuis l'onglet SAC ou le MENU RAPIDE. Plus besoin de rentrer en ville.", de = "Öffne deine Boxen über BEUTEL oder das SCHNELLMENÜ. Kein Weg zurück in die Stadt.", it = "Apri i box dalla scheda BORSA o dal MENU RAPIDO. Niente ritorno in città.", es = "Abre tus cajas desde MOCHILA o el MENÚ RÁPIDO. Sin volver a la ciudad.", br = "Abra suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade.", pt = "Abra as suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade.", zh = "通过背包标签页或快捷菜单打开盒子，无需走回城镇。"),
    "OPEN PC" to Tr(ja = "パソコンを ひらく", fr = "OUVRIR LE PC", de = "PC ÖFFNEN", it = "APRI IL PC", es = "ABRIR PC", br = "ABRIR PC", pt = "ABRIR PC", zh = "打开电脑"),
    "NO NEED TO HOLD B" to Tr(ja = "Bを おさなくて いい", fr = "PLUS BESOIN DE TENIR B", de = "B NICHT MEHR HALTEN", it = "NON SERVE TENERE B", es = "SIN MANTENER B", br = "SEM SEGURAR B", pt = "SEM MANTER B", zh = "无需按住 B"),
    "AUTO-RUN makes you run on the field by itself. Hold B when you want to walk." to Tr(ja = "オートダッシュで いつでも はしる。 あるきたい ときは Bを おす。", fr = "COURSE AUTO vous fait courir tout seul. Maintenez B pour marcher.", de = "AUTO-RENNEN lässt dich von selbst rennen. Halte B, um zu gehen.", it = "CORSA AUTO ti fa correre da solo. Tieni premuto B per camminare.", es = "CORRER AUTO te hace correr solo. Mantén B para caminar.", br = "CORRIDA AUTO faz você correr sozinho. Segure B para andar.", pt = "CORRIDA AUTO faz você correr sozinho. Mantenha B para andar.", zh = "自动跑步会让你在场景中自动奔跑。想走路时按住 B。"),
    "TIRED OF WILD BATTLES?" to Tr(ja = "やせいの バトルに つかれた?", fr = "MARRE DES COMBATS SAUVAGES ?", de = "GENUG VON WILDEN KÄMPFEN?", it = "STANCO DEI SELVATICI?", es = "¿HARTO DE LOS SALVAJES?", br = "CANSADO DE BATALHAS SELVAGENS?", pt = "FARTO DE BATALHAS SELVAGENS?", zh = "厌倦了野生对战？"),
    "Switch wild encounters off for a while. Fishing and story battles still happen." to Tr(ja = "やせいの ポケモンを しばらく オフに。 つりと イベントの バトルは そのまま。", fr = "Coupez les POKéMON SAUVAGES un moment. La pêche et les combats de l'histoire restent.", de = "Schalte WILDE POKéMON eine Weile ab. Angeln und Kämpfe der Geschichte bleiben.", it = "Spegni i POKéMON SELVATICI per un po'. Pesca e lotte della storia restano.", es = "Apaga los POKéMON SALVAJES un rato. La pesca y los combates de la historia siguen.", br = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam.", pt = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam.", zh = "可以暂时关闭野生遭遇，钓鱼和剧情对战仍会发生。"),
    "SWITCH OFF" to Tr(ja = "オフにする", fr = "COUPER", de = "ABSCHALTEN", it = "SPEGNI", es = "APAGAR", br = "DESLIGAR", pt = "DESLIGAR", zh = "关闭"),
    "KEEP YOUR TMS" to Tr(ja = "わざマシンを なくさない", fr = "GARDEZ VOS CT", de = "BEHALTE DEINE TM", it = "TIENI LE MT", es = "CONSERVA TUS MT", br = "GUARDE SEUS MTs", pt = "GUARDE OS SEUS MTs", zh = "保留招式学习器"),
    "With REUSABLE TMS a TM stays in your bag after it teaches a move." to Tr(ja = "マシン むげん なら おしえた あとも わざマシンが バッグに のこる。", fr = "Avec CT ILLIMITÉES, une CT reste dans le sac après usage.", de = "Mit TM BLEIBEN bleibt eine TM nach dem Lehren im Beutel.", it = "Con MT ILLIMITATE una MT resta nella borsa dopo l'uso.", es = "Con MT ILIMITADAS una MT sigue en la mochila tras usarla.", br = "Com MT ILIMITADOS um MT fica na mochila depois de usado.", pt = "Com MT ILIMITADOS um MT fica na mochila depois de usado.", zh = "开启可重复使用招式学习器后，教学完成的学习器仍留在背包中。"),
    "FLY WITHOUT THE MENUS" to Tr(ja = "メニュー なしで そらをとぶ", fr = "VOLER SANS LES MENUS", de = "FLIEGEN OHNE MENÜS", it = "VOLA SENZA MENU", es = "VUELA SIN MENÚS", br = "VOE SEM MENUS", pt = "VOE SEM MENUS", zh = "无需打开菜单即可飞翔"),
    "Pick a town you've been to and fly there: FLY on the MAP, or in the QUICK MENU." to Tr(ja = "いった まちを えらんで ひとっとび。 マップか クイックメニューの そらをとぶで。", fr = "Choisissez une ville déjà visitée et volez-y : VOL sur la CARTE ou dans le MENU RAPIDE.", de = "Wähle eine besuchte Stadt und flieg hin: FLIEGEN auf der KARTE oder im SCHNELLMENÜ.", it = "Scegli una città già visitata e volaci: VOLO sulla MAPPA o nel MENU RAPIDO.", es = "Elige una ciudad visitada y vuela allí: VUELO en el MAPA o en el MENÚ RÁPIDO.", br = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO.", pt = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO.", zh = "选择去过的城镇并飞往那里：使用地图或快捷菜单中的飞翔。"),
    "FLY NOW" to Tr(ja = "そらをとぶ", fr = "VOLER", de = "FLIEGEN", it = "VOLA", es = "VOLAR", br = "VOAR", pt = "VOAR", zh = "立即飞翔"),
    "RIGHT STICK" to Tr(ja = "みぎスティック", fr = "STICK DROIT", de = "RECHTER STICK", it = "STICK DESTRO", es = "STICK DERECHO", br = "ANALÓGICO DIREITO", pt = "ANALÓGICO DIREITO", zh = "右摇杆"),
    "LOOK AROUND" to Tr(ja = "みまわす", fr = "REGARDER", de = "UMSEHEN", it = "GUARDA INTORNO", es = "MIRAR", br = "OLHAR", pt = "OLHAR", zh = "环顾四周"),
)
